# ============================ SETTINGS ============================

# Camera settings match the new 1820-image white-frame dataset.
FRAME_SIZE = "QVGA"
PIXFORMAT = "RGB565"
# The result is fused over later live frames, so a long one-second camera
# warm-up is unnecessary in the 10-second competition window.
CAMERA_SETTLE_MS = 250
FREEZE_AUTO_CONTROLS = True

# Keep this True while checking aim and overlays in OpenMV IDE. Set it False
# for the competition after alignment is fixed to remove USB preview overhead.
IDE_STREAM_ENABLED = True

# Phase-one bench mode: the scan frequency is known and fixed at 1 kHz.
SCAN_FREQUENCY_HZ = 1000

# Three independent classifications are fused with a median. Rolling
# validation: 98.85% within 100 Hz and 100% within 200 Hz.
FUSION_FRAMES = 3
# The camera and white frame are stationary during one measurement. Reuse
# the last reliable screen rectangle across short threshold/blob misses.
SCREEN_TRACK_HOLD_FRAMES = 20

# Console output is intentionally short: one Chinese summary per second.
PUBLISH_PERIOD_MS = 1000
ACCEPT_CONFIDENCE = 45
CONSOLE_DEBUG = False

# The console result is more conservative than the three-frame image
# overlay. It clusters about one second of raw predictions and suppresses
# isolated aliases before showing a value to the operator.
CONSOLE_WINDOW_FRAMES = 12
CONSOLE_MIN_SAMPLES = 8
CONSOLE_CLUSTER_RADIUS = 0.3
CONSOLE_MIN_CONFIDENCE = 50
CONSOLE_NO_TRACE_RESET_MS = 1200

# OLED remains only an aiming aid and is updated at a low rate.
OLED_ENABLED = True
OLED_MAX_FPS = 2
OLED_I2C_ID = 2
OLED_SCL_PIN = "P7"
OLED_SDA_PIN = "P8"
OLED_ADDRESS = 0x3C
OLED_CONTRAST_PERCENT = 200
OLED_COLUMN_OFFSET = 0
OLED_FAST_START = True
# Only the centered 64x32 preview is refreshed at runtime. Clear the full
# 128x64 controller RAM once so the untouched border remains black.
OLED_CLEAR_ON_START = True

