# ======================== PCA/KNN CLASSIFIER ======================

class RatioResult:
    def __init__(self):
        self.found = False
        self.accepted = False
        self.rect = None
        self.patch_rect = None
        self.frame_ratio = 0.0
        self.ratio = 0.0
        self.estimated_frequency_hz = 0
        self.confidence = 0
        self.stable_frames = 0
        self.predictions = ()
        self.nearest_distance = 0.0
        self.second_distance = 0.0
        self.analysis_ms = 0
        self.method = "WHITE-PCA-KNN"
        self.tracked_rect = False
        self.failure_reason = ""

    def clear(self):
        self.found = False
        self.accepted = False
        self.rect = None
        self.patch_rect = None
        self.frame_ratio = 0.0
        self.ratio = 0.0
        self.estimated_frequency_hz = 0
        self.confidence = 0
        self.stable_frames = 0
        self.predictions = ()
        self.nearest_distance = 0.0
        self.second_distance = 0.0
        self.analysis_ms = 0
        self.tracked_rect = False
        self.failure_reason = ""
        return self


def _clamp(value, low, high):
    if value < low:
        return low
    if value > high:
        return high
    return value


def _ticks_ms():
    return time.ticks_ms()


def _ticks_diff(new, old):
    return time.ticks_diff(new, old)


def _decode_base64_parts(parts):
    decoded = []
    for part in parts:
        decoded.append(binascii.a2b_base64(part))
    return b"".join(decoded)


class PcaRatioClassifier:
    def __init__(
        self,
        fusion_frames=3,
        accept_confidence=45,
        screen_hold_frames=20,
    ):
        self.fusion_frames = fusion_frames
        self.accept_confidence = accept_confidence
        self.screen_hold_frames = screen_hold_frames
        self.result = RatioResult()
        self.history = []
        self.frame_confidences = []
        self.last_screen_rect = None
        self.screen_miss_count = 0

        weight_bytes = _decode_base64_parts(MODEL_WEIGHT_B64_PARTS)
        exemplar_bytes = _decode_base64_parts(MODEL_EXEMPLAR_B64_PARTS)
        self.label_bytes = _decode_base64_parts(MODEL_LABEL_B64_PARTS)

        self.weights = np.array(
            np.frombuffer(weight_bytes, dtype=np.int8),
            dtype=np.float,
        ).reshape((MODEL_COMPONENTS, MODEL_FEATURE_COUNT))
        self.weight_scales = np.array(
            MODEL_WEIGHT_SCALES,
            dtype=np.float,
        )
        self.biases = np.array(MODEL_BIASES, dtype=np.float)

        # Float exemplars prevent int8 subtraction overflow. N6 has ample
        # SDRAM for the 1820x40 matrix.
        self.exemplars = np.array(
            np.frombuffer(exemplar_bytes, dtype=np.int8),
            dtype=np.float,
        ).reshape((MODEL_EXEMPLARS, MODEL_COMPONENTS))
        # Precompute ||exemplar||^2 once. Per-frame distances can then use
        # ||e-q||^2 = ||e||^2 - 2(e.q) + ||q||^2, avoiding a large
        # 1820x40 temporary array and any dependency on 2-D broadcasting.
        self.exemplar_norms = np.sum(
            self.exemplars * self.exemplars,
            axis=1,
        )

    def reset_history(self):
        self.history = []
        self.frame_confidences = []

    @staticmethod
    def _blob_rect(blob):
        # OpenMV v5 exposes blob fields as attributes (blob.rect is a
        # tuple), while older firmware exposed callable accessors. Accept
        # both so the generated single file cannot call a tuple.
        value = blob.rect
        if isinstance(value, tuple):
            return value
        return value()

    @staticmethod
    def _blob_pixels(blob):
        value = blob.pixels
        if isinstance(value, int):
            return value
        return value()

    @staticmethod
    def _select_blob(mask):
        frame_width = mask.width()
        frame_height = mask.height()
        blobs = mask.find_blobs(
            [(1, 255)],
            x_stride=1,
            y_stride=1,
            area_threshold=500,
            pixels_threshold=250,
            merge=True,
            margin=2,
        )

        best_blob = None
        best_score = -1.0
        for blob in blobs:
            x, y, width, height = PcaRatioClassifier._blob_rect(blob)
            center_x = x + (0.5 * width)
            aspect = width / max(1.0, height)

            # The white paper frame isolates the intended dark XY screen.
            # These bounds reject the narrow left display and the dark
            # oscilloscope body outside the paper.
            if width < (0.22 * frame_width):
                continue
            if width > (0.52 * frame_width):
                continue
            if height < (0.35 * frame_height):
                continue
            if height > (0.82 * frame_height):
                continue
            if aspect < 0.62 or aspect > 1.35:
                continue
            if center_x < (0.36 * frame_width):
                continue
            if center_x > (0.68 * frame_width):
                continue
            center_y = y + (0.5 * height)
            if center_y < (0.20 * frame_height):
                continue
            if center_y > (0.80 * frame_height):
                continue

            pixels = PcaRatioClassifier._blob_pixels(blob)
            if (pixels * 5) < (width * height):
                continue
            score = pixels
            if score > best_score:
                best_blob = blob
                best_score = score
        return best_blob

    @staticmethod
    def _make_screen_mask(frame):
        # The high-contrast white paper breaks the central dark display
        # away from the rest of the black oscilloscope. One grayscale
        # threshold is both faster and more stable than using the changing
        # green trace itself as the crop boundary.
        dark_screen = frame.to_grayscale(copy=True)
        dark_screen.binary([(0, MODEL_SCREEN_DARK_MAX)])
        return dark_screen

    @staticmethod
    def _patch_rect(blob_rect, frame_width, frame_height):
        x, y, width, height = blob_rect
        margin_x = max(
            1,
            int(round(
                width * MODEL_SCREEN_MARGIN_X1000 / 1000.0
            )),
        )
        margin_y = max(
            1,
            int(round(
                height * MODEL_SCREEN_MARGIN_X1000 / 1000.0
            )),
        )
        patch_x = x + margin_x
        patch_y = y + margin_y
        patch_width = width - (2 * margin_x)
        patch_height = height - (2 * margin_y)
        if patch_width < 32 or patch_height < 32:
            return None

        if patch_x < 0 or patch_y < 0:
            return None
        if patch_x + patch_width > frame_width:
            return None
        if patch_y + patch_height > frame_height:
            return None
        return (
            patch_x,
            patch_y,
            patch_width,
            patch_height,
        )

    def _extract_feature(self, frame, patch_rect):
        patch = frame.to_grayscale(
            x_scale=(
                (MODEL_FEATURE_SIDE + 0.01)
                / float(patch_rect[2])
            ),
            y_scale=(
                (MODEL_FEATURE_SIDE + 0.01)
                / float(patch_rect[3])
            ),
            roi=patch_rect,
            hint=omv_image.BILINEAR,
            copy=True,
        )
        if (
            patch.width() != MODEL_FEATURE_SIDE
            or patch.height() != MODEL_FEATURE_SIDE
        ):
            return None

        feature = patch.to_ndarray("f").flatten()
        mean = np.mean(feature)
        std = np.std(feature)
        if std < 3.0:
            return None
        return (feature - mean) / std

    def _classify_feature(self, feature):
        projection = (
            np.dot(self.weights, feature) * self.weight_scales
        ) + self.biases

        # OpenMV v5.0.0 ulab deliberately implements only a NumPy subset
        # and has no np.round(). Quantize the PCA values explicitly;
        # the loop is tiny and exactly matches the PC model's nearest-
        # integer/clamp operation for non-tie values.
        quantized_values = []
        for component in range(MODEL_COMPONENTS):
            value = (
                float(projection[component])
                * MODEL_PROJECTION_QUANTIZATION
            )
            if value >= 0.0:
                value = int(value + 0.5)
            else:
                value = int(value - 0.5)
            quantized_values.append(int(_clamp(value, -127, 127)))
        quantized = np.array(
            quantized_values,
            dtype=np.float,
        )

        quantized_norm = float(np.sum(quantized * quantized))
        distances = (
            self.exemplar_norms
            - (2.0 * np.dot(self.exemplars, quantized))
            + quantized_norm
        )
        nearest_index = int(np.argmin(distances))
        best_label = self.label_bytes[nearest_index]
        nearest_distance = float(distances[nearest_index])

        # There are exactly 20 exemplars per frequency. Repeated ulab
        # argmin calls run in C and are much faster than inspecting all
        # 1820 distances in a MicroPython loop. After at most 20 removals,
        # the next item must belong to another label.
        second_distance = 1.0e30
        for _ in range(21):
            candidate_index = int(np.argmin(distances))
            candidate_distance = float(distances[candidate_index])
            if self.label_bytes[candidate_index] != best_label:
                second_distance = candidate_distance
                break
            distances[candidate_index] = 1.0e30

        if second_distance <= 0.0:
            frame_confidence = 0
        else:
            frame_confidence = int(
                100.0
                * (second_distance - nearest_distance)
                / second_distance
            )
        frame_confidence = int(_clamp(frame_confidence, 0, 99))
        return (
            int(best_label),
            frame_confidence,
            nearest_distance,
            second_distance,
        )

    def analyze(self, frame, scan_frequency_hz=1000):
        started = _ticks_ms()
        result = self.result.clear()

        mask = self._make_screen_mask(frame)
        blob = self._select_blob(mask)
        if blob is None:
            self.screen_miss_count += 1
            if (
                self.last_screen_rect is None
                or self.screen_miss_count > self.screen_hold_frames
            ):
                self.last_screen_rect = None
                self.reset_history()
                result.failure_reason = "NO_SCREEN"
                result.analysis_ms = _ticks_diff(
                    _ticks_ms(),
                    started,
                )
                return result
            blob_rect = self.last_screen_rect
            result.tracked_rect = True
        else:
            blob_rect = self._blob_rect(blob)
            self.last_screen_rect = blob_rect
            self.screen_miss_count = 0

        patch_rect = self._patch_rect(
            blob_rect,
            frame.width(),
            frame.height(),
        )
        if patch_rect is None:
            self.reset_history()
            result.failure_reason = "BAD_ROI"
            result.analysis_ms = _ticks_diff(_ticks_ms(), started)
            return result

        feature = self._extract_feature(frame, patch_rect)
        if feature is None:
            self.reset_history()
            result.failure_reason = "BAD_PATCH"
            result.analysis_ms = _ticks_diff(_ticks_ms(), started)
            return result

        (
            label,
            frame_confidence,
            nearest_distance,
            second_distance,
        ) = self._classify_feature(feature)

        self.history.append(label)
        self.frame_confidences.append(frame_confidence)
        if len(self.history) > self.fusion_frames:
            self.history.pop(0)
            self.frame_confidences.pop(0)

        ordered = sorted(self.history)
        fused_label = ordered[len(ordered) // 2]
        ratio = 1.0 + (0.1 * fused_label)
        frame_ratio = 1.0 + (0.1 * label)

        deviations = sorted(
            abs(value - fused_label) for value in self.history
        )
        median_deviation = deviations[len(deviations) // 2]
        stability_confidence = int(
            _clamp(100 - (25 * median_deviation), 0, 100)
        )
        distance_confidence = (
            sum(self.frame_confidences)
            // max(1, len(self.frame_confidences))
        )
        confidence = int(
            (0.45 * distance_confidence)
            + (0.55 * stability_confidence)
        )
        if len(self.history) < self.fusion_frames:
            confidence = min(confidence, 44)

        result.found = True
        result.rect = blob_rect
        result.patch_rect = patch_rect
        result.frame_ratio = frame_ratio
        result.ratio = ratio
        result.estimated_frequency_hz = int(
            round(ratio * scan_frequency_hz / 100.0) * 100
        )
        result.confidence = int(_clamp(confidence, 0, 99))
        result.stable_frames = len(self.history)
        result.predictions = tuple(
            1.0 + (0.1 * value) for value in self.history
        )
        result.nearest_distance = nearest_distance
        result.second_distance = second_distance
        result.accepted = (
            len(self.history) >= self.fusion_frames
            and result.confidence >= self.accept_confidence
        )
        result.analysis_ms = _ticks_diff(_ticks_ms(), started)
        return result

# ========================== SSD1309 OLED ==========================

try:
    import micropython
    _native = getattr(micropython, "native", None)
except ImportError:
    _native = None

if _native is None:
    def _native(function):
        return function


PANEL_WIDTH = 128
PANEL_HEIGHT = 64
OLED_WIDTH = 64
OLED_HEIGHT = 32


def _ticks_ms():
    function = getattr(time, "ticks_ms", None)
    if function:
        return function()
    return int(time.time() * 1000)


def _ticks_diff(new, old):
    function = getattr(time, "ticks_diff", None)
    if function:
        return function(new, old)
    return new - old


def _adjust_threshold(value, brightness, contrast_percent):
    delta = value - 128
    if delta < 0:
        value = 128 - ((-delta * 100) // contrast_percent)
    else:
        value = 128 + ((delta * 100) // contrast_percent)
    value -= brightness
    if value < 0:
        return 0
    if value > 255:
        return 255
    return value


@_native
def _pack_grayscale(
    src,
    dst,
    source_width,
    x_map,
    y_map,
    threshold_x0,
    threshold_x1,
    threshold_x2,
    threshold_x3,
):
    output = 1
    for page in range(OLED_HEIGHT // 8):
        y = page * 8
        row0 = y_map[y] * source_width
        row1 = y_map[y + 1] * source_width
        row2 = y_map[y + 2] * source_width
        row3 = y_map[y + 3] * source_width
        row4 = y_map[y + 4] * source_width
        row5 = y_map[y + 5] * source_width
        row6 = y_map[y + 6] * source_width
        row7 = y_map[y + 7] * source_width

        for x in range(OLED_WIDTH):
            source_x = x_map[x]
            dst[output] = (
                (1 if src[row0 + source_x] >= threshold_x0[x] else 0)
                | (2 if src[row1 + source_x] >= threshold_x1[x] else 0)
                | (4 if src[row2 + source_x] >= threshold_x2[x] else 0)
                | (8 if src[row3 + source_x] >= threshold_x3[x] else 0)
                | (16 if src[row4 + source_x] >= threshold_x0[x] else 0)
                | (32 if src[row5 + source_x] >= threshold_x1[x] else 0)
                | (64 if src[row6 + source_x] >= threshold_x2[x] else 0)
                | (128 if src[row7 + source_x] >= threshold_x3[x] else 0)
            )
            output += 1


@_native
def _pack_rgb565(
    src,
    dst,
    source_width,
    x_map,
    y_map,
    threshold_x0,
    threshold_x1,
    threshold_x2,
    threshold_x3,
):
    """Downsample a little-endian RGB565 frame directly into SSD1309 pages."""
    output = 1
    for page in range(OLED_HEIGHT // 8):
        y = page * 8
        row0 = y_map[y] * source_width
        row1 = y_map[y + 1] * source_width
        row2 = y_map[y + 2] * source_width
        row3 = y_map[y + 3] * source_width
        row4 = y_map[y + 4] * source_width
        row5 = y_map[y + 5] * source_width
        row6 = y_map[y + 6] * source_width
        row7 = y_map[y + 7] * source_width
        rows = (row0, row1, row2, row3, row4, row5, row6, row7)

        for x in range(OLED_WIDTH):
            source_x = x_map[x]
            bits = 0
            for bit in range(8):
                byte_index = (rows[bit] + source_x) << 1
                pixel = src[byte_index] | (src[byte_index + 1] << 8)
                red5 = (pixel >> 11) & 0x1F
                green6 = (pixel >> 5) & 0x3F
                blue5 = pixel & 0x1F
                gray = (
                    (red5 * 616)
                    + (green6 * 600)
                    + (blue5 * 232)
                ) >> 8
                phase = bit & 3
                if phase == 0:
                    threshold = threshold_x0[x]
                elif phase == 1:
                    threshold = threshold_x1[x]
                elif phase == 2:
                    threshold = threshold_x2[x]
                else:
                    threshold = threshold_x3[x]
                if gray >= threshold:
                    bits |= 1 << bit
            dst[output] = bits
            output += 1


class AimDisplay:
    def __init__(
        self,
        max_fps=3,
        brightness=0,
        contrast_percent=200,
        oled_contrast=0xFF,
        address=0x3C,
        column_offset=0,
        hardware_bus=2,
        scl_pin="P4",
        sda_pin="P5",
        allow_soft_fallback=True,
        fast_start=False,
        clear_on_start=True,
        self_test=True,
    ):
        if max_fps <= 0:
            raise ValueError("max_fps must be positive")
        if contrast_percent <= 0:
            raise ValueError("contrast_percent must be positive")

        self.enabled = True
        self.period_ms = max(1, 1000 // max_fps)
        self.last_update = None
        self.last_duration_ms = 0
        self.update_count = 0
        self.error_count = 0
        self.source_width = 0
        self.source_height = 0
        self.x_map = None
        self.y_map = None

        self.address_requested = address
        self.column_offset = column_offset
        self.oled_contrast = oled_contrast
        self.tx = bytearray(1 + (OLED_WIDTH * OLED_HEIGHT // 8))
        self.tx[0] = 0x40

        rows = (
            (8, 136, 40, 168),
            (200, 72, 232, 104),
            (56, 184, 24, 152),
            (248, 120, 216, 88),
        )
        adjusted = []
        for row in rows:
            adjusted.append(tuple(
                _adjust_threshold(value, brightness, contrast_percent)
                for value in row
            ))
        self.threshold_x0 = bytes(
            adjusted[0][x & 3] for x in range(OLED_WIDTH)
        )
        self.threshold_x1 = bytes(
            adjusted[1][x & 3] for x in range(OLED_WIDTH)
        )
        self.threshold_x2 = bytes(
            adjusted[2][x & 3] for x in range(OLED_WIDTH)
        )
        self.threshold_x3 = bytes(
            adjusted[3][x & 3] for x in range(OLED_WIDTH)
        )

        self.i2c, self.address, self.bus_mode, self.bus_frequency = (
            self._open_bus(
                hardware_bus,
                scl_pin,
                sda_pin,
                allow_soft_fallback,
                fast_start,
            )
        )
        first_column = (
            self.column_offset + ((PANEL_WIDTH - OLED_WIDTH) // 2)
        )
        first_page = (PANEL_HEIGHT - OLED_HEIGHT) // 16
        self.window = bytes((
            0x00,
            0x21, first_column, first_column + OLED_WIDTH - 1,
            0x22,
            first_page,
            first_page + (OLED_HEIGHT // 8) - 1,
        ))
        self._init_display(clear_panel=clear_on_start)
        if self_test:
            self._show_self_test()

    def _select_address(self, found):
        for candidate in (self.address_requested, 0x3C, 0x3D):
            if candidate in found:
                return candidate
        return None

    def _open_bus(
        self,
        hardware_bus,
        scl_pin,
        sda_pin,
        allow_soft_fallback,
        fast_start,
    ):
        if fast_start:
            # The competition wiring is fixed and already verified:
            # P7=SCL, P8=SDA, 100 kHz, address 0x3C. Do not spend time
            # scanning four bus/frequency combinations at every boot.
            bus = SoftI2C(
                scl=Pin(scl_pin),
                sda=Pin(sda_pin),
                freq=100_000,
            )
            return (
                bus,
                self.address_requested,
                "software",
                100_000,
            )

        for frequency in (400_000, 100_000):
            bus = None
            try:
                bus = I2C(hardware_bus, freq=frequency)
                found = bus.scan()
                address = self._select_address(found)
                if address is not None:
                    return bus, address, "hardware", frequency
            except (OSError, ValueError):
                pass
            if bus is not None:
                try:
                    bus.deinit()
                except (AttributeError, OSError):
                    pass

        if allow_soft_fallback:
            # P7/P8 uses bit-banged I2C on N6. Long wires and typical OLED
            # pull-ups repeatedly NACKed at 400 kHz in the user's log.
            for frequency in (100_000, 50_000):
                try:
                    bus = SoftI2C(
                        scl=Pin(scl_pin),
                        sda=Pin(sda_pin),
                        freq=frequency,
                    )
                    found = bus.scan()
                    address = self._select_address(found)
                    if address is not None:
                        return bus, address, "software", frequency
                except (OSError, ValueError):
                    pass

        raise RuntimeError(
            "SSD1309 not found on P4/P5 or P7/P8; check 3V3/GND/pull-ups"
        )

    def _commands(self, values):
        packet = bytearray(len(values) + 1)
        packet[0] = 0x00
        packet[1:] = values
        self.i2c.writeto(self.address, packet)

    def _init_display(self, clear_panel=True):
        self._commands(bytes((
            0xAE,
            0xD5, 0x80,
            0xA8, 0x3F,
            0xD3, 0x00,
            0x40,
            0x20, 0x00,
            0xA1,
            0xC8,
            0xDA, 0x12,
            0x81, self.oled_contrast,
            0xD9, 0xF1,
            0xDB, 0x40,
            0xA4,
            0xA6,
            0xAF,
        )))
        if clear_panel:
            self._clear_panel()

    def _clear_panel(self):
        """Clear the 128x64 RAM in short page writes to avoid SoftI2C NACKs."""
        packet = bytearray(1 + PANEL_WIDTH)
        packet[0] = 0x40
        for page in range(PANEL_HEIGHT // 8):
            window = bytes((
                0x00,
                0x21, self.column_offset,
                self.column_offset + PANEL_WIDTH - 1,
                0x22, page, page,
            ))
            self.i2c.writeto(self.address, window)
            self.i2c.writeto(self.address, packet)

    def _show(self):
        self.i2c.writeto(self.address, self.window)
        self.i2c.writeto(self.address, self.tx)

    def _show_self_test(self):
        """Show a border and X immediately so wiring is visible at boot."""
        for page in range(OLED_HEIGHT // 8):
            for x in range(OLED_WIDTH):
                value = 0
                if page == 0:
                    value |= 0x01
                if page == (OLED_HEIGHT // 8) - 1:
                    value |= 0x80
                if x == 0 or x == OLED_WIDTH - 1:
                    value = 0xFF

                y0 = (x * (OLED_HEIGHT - 1)) // (OLED_WIDTH - 1)
                y1 = (OLED_HEIGHT - 1) - y0
                if (y0 >> 3) == page:
                    value |= 1 << (y0 & 7)
                if (y1 >> 3) == page:
                    value |= 1 << (y1 & 7)
                self.tx[1 + (page * OLED_WIDTH) + x] = value
        self._show()
        self.last_update = _ticks_ms()

    def _ensure_maps(self, width, height):
        if width < 2 or height < 2:
            raise ValueError("source image must be at least 2x2")
        if width == self.source_width and height == self.source_height:
            return
        self.source_width = width
        self.source_height = height
        self.x_map = array(
            "H",
            [
                (x * (width - 1)) // (OLED_WIDTH - 1)
                for x in range(OLED_WIDTH)
            ],
        )
        self.y_map = array(
            "H",
            [
                (y * (height - 1)) // (OLED_HEIGHT - 1)
                for y in range(OLED_HEIGHT)
            ],
        )

    def set_max_fps(self, max_fps):
        if max_fps <= 0:
            raise ValueError("max_fps must be positive")
        self.period_ms = max(1, 1000 // max_fps)

    def update_if_due(self, frame, now_ms=None, force=False):
        if not self.enabled:
            return False
        if now_ms is None:
            now_ms = _ticks_ms()
        if (
            not force
            and self.last_update is not None
            and _ticks_diff(now_ms, self.last_update) < self.period_ms
        ):
            return False

        start = _ticks_ms()
        width = frame.width()
        height = frame.height()
        self._ensure_maps(width, height)
        source = frame.bytearray()
        packer = (
            _pack_grayscale
            if frame.format() == omv_image.GRAYSCALE
            else _pack_rgb565
        )
        packer(
            source,
            self.tx,
            self.source_width,
            self.x_map,
            self.y_map,
            self.threshold_x0,
            self.threshold_x1,
            self.threshold_x2,
            self.threshold_x3,
        )

        # Four blinking pixels in the top-right corner prove that the OLED
        # loop is alive even when the camera and scope image are stationary.
        heartbeat_on = (self.update_count & 1) == 0
        for x in range(OLED_WIDTH - 4, OLED_WIDTH):
            index = 1 + x
            if heartbeat_on:
                self.tx[index] |= 0x0F
            else:
                self.tx[index] &= 0xF0

        self._show()
        done = _ticks_ms()
        self.last_duration_ms = _ticks_diff(done, start)
        self.last_update = now_ms
        self.update_count += 1
        self.error_count = 0
        return True

# ============================= APP ================================

def ticks_ms():
    return time.ticks_ms()


def ticks_diff(new, old):
    return time.ticks_diff(new, old)


def setup_camera():
    camera = csi.CSI(stream=IDE_STREAM_ENABLED)
    camera.reset()
    camera.pixformat(csi.RGB565)
    camera.framesize(csi.QVGA)
    camera.snapshot(time=CAMERA_SETTLE_MS)

    if FREEZE_AUTO_CONTROLS:
        try:
            camera.auto_gain(False)
        except (AttributeError, OSError):
            pass
        try:
            camera.auto_exposure(False)
        except (AttributeError, OSError):
            pass
        try:
            camera.auto_whitebal(False)
        except (AttributeError, OSError):
            pass
    return camera


def setup_display():
    if not OLED_ENABLED:
        print("【OLED】已关闭")
        return None
    try:
        display = AimDisplay(
            max_fps=OLED_MAX_FPS,
            contrast_percent=OLED_CONTRAST_PERCENT,
            address=OLED_ADDRESS,
            column_offset=OLED_COLUMN_OFFSET,
            hardware_bus=OLED_I2C_ID,
            scl_pin=OLED_SCL_PIN,
            sda_pin=OLED_SDA_PIN,
            allow_soft_fallback=True,
            fast_start=OLED_FAST_START,
            clear_on_start=OLED_CLEAR_ON_START,
            self_test=False,
        )
        return display
    except (ImportError, RuntimeError, ValueError, OSError) as error:
        print("【OLED】未连接，识别功能不受影响：%s" % error)
        return None


def state_name(result):
    if result.accepted:
        return "OK"
    if result.found:
        return "ACQUIRE"
    return "NO_TRACE"


def prediction_text(result):
    if not result.predictions:
        return "--"
    return ",".join("%.1f" % value for value in result.predictions)


def console_consensus(history):
    """Return a robust operator-facing result from recent raw predictions."""
    if len(history) < CONSOLE_MIN_SAMPLES:
        return None

    best_group = None
    best_spread = 1.0e30
    for center in history:
        group = [
            value
            for value in history
            if abs(value - center) <= CONSOLE_CLUSTER_RADIUS
        ]
        spread = sum(abs(value - center) for value in group)
        if (
            best_group is None
            or len(group) > len(best_group)
            or (len(group) == len(best_group) and spread < best_spread)
        ):
            best_group = group
            best_spread = spread

    ordered = sorted(best_group)
    ratio = ordered[len(ordered) // 2]
    confidence = int(100 * len(best_group) / len(history))
    return ratio, confidence, len(best_group), len(history)


def annotate(frame, result, fps, oled_ms):
    state = state_name(result)
    if state == "OK":
        color = (40, 255, 40)
    elif state == "ACQUIRE":
        color = (80, 180, 255)
    else:
        color = (255, 60, 60)

    if result.rect is not None:
        frame.draw_rectangle(result.rect, color=color, thickness=2)
    if result.patch_rect is not None:
        frame.draw_rectangle(
            result.patch_rect,
            color=(255, 220, 0),
            thickness=1,
        )

    frame.draw_rectangle(
        (0, 0, frame.width(), 38),
        color=(0, 0, 0),
        fill=True,
    )
    frame.draw_string(
        (2, 1),
        "%s SCAN:1000Hz RATIO:%4.1fx" % (state, result.ratio),
        color=color,
        scale=1,
    )
    frame.draw_string(
        (2, 13),
        "EST:%5dHz CONF:%2d%% AI:%dms"
        % (
            result.estimated_frequency_hz,
            result.confidence,
            result.analysis_ms,
        ),
        color=(255, 255, 255),
        scale=1,
    )
    frame.draw_string(
        (2, 25),
        "VOTE:%s FPS:%.1f OLED:%dms"
        % (
            prediction_text(result),
            fps,
            oled_ms,
        ),
        color=(200, 220, 255),
        scale=1,
    )


try:
    boot_started = SCRIPT_STARTED_MS
except NameError:
    boot_started = ticks_ms()
print("")
print("【启动】1 kHz 白框定位模型 v2 正在快速初始化……")
camera = setup_camera()

display = setup_display()

classifier = PcaRatioClassifier(
    fusion_frames=FUSION_FRAMES,
    accept_confidence=ACCEPT_CONFIDENCE,
    screen_hold_frames=SCREEN_TRACK_HOLD_FRAMES,
)
print(
    "【就绪】启动用时%dms；扫描频率1000 Hz，"
    "请让白框和中央屏幕完整入镜"
    % ticks_diff(ticks_ms(), boot_started)
)
print("")

clock = time.clock()
last_publish = ticks_ms()
last_trace_ms = last_publish
console_history = []

while True:
    clock.tick()
    frame = camera.snapshot()
    result = classifier.analyze(
        frame,
        scan_frequency_hz=SCAN_FREQUENCY_HZ,
    )
    now = ticks_ms()

    if result.found:
        last_trace_ms = now
        console_history.append(result.frame_ratio)
        if len(console_history) > CONSOLE_WINDOW_FRAMES:
            console_history.pop(0)
    elif (
        ticks_diff(now, last_trace_ms)
        >= CONSOLE_NO_TRACE_RESET_MS
    ):
        console_history = []

    oled_ms = display.last_duration_ms if display is not None else -1

    if ticks_diff(now, last_publish) >= PUBLISH_PERIOD_MS:
        consensus = console_consensus(console_history)
        if consensus is not None:
            ratio, confidence, agreeing, total = consensus
            if confidence < CONSOLE_MIN_CONFIDENCE:
                print("【结果不稳定】波形变化较大，请保持相机和信号不动")
            else:
                frequency_hz = int(
                    round(ratio * SCAN_FREQUENCY_HZ)
                )
                if confidence >= 70:
                    result_title = "稳定结果"
                else:
                    result_title = "参考结果"
                print(
                    "【%s】正弦波约%d Hz（%.1f倍），可信度%d%%，帧率%.1f"
                    % (
                        result_title,
                        frequency_hz,
                        ratio,
                        confidence,
                        clock.fps(),
                    )
                )
        elif not console_history:
            if result.failure_reason == "BAD_PATCH":
                print(
                    "【特征尺寸异常】屏幕已找到但缩放失败，"
                    "请保持白框完整"
                )
            elif result.failure_reason == "BAD_ROI":
                print(
                    "【屏幕框异常】请让中央黑色屏幕完整位于画面内"
                )
            else:
                print(
                    "【未找到屏幕】请让白框和中央黑色屏幕完整入镜"
                )
        else:
            print(
                "【识别中】已取得%d/%d个有效画面，请保持不动"
                % (len(console_history), CONSOLE_MIN_SAMPLES)
            )

        if CONSOLE_DEBUG:
            print(
                "  调试：单帧=%.1f倍，三帧=%.1f倍，置信度=%d%%，"
                "耗时=%dms，框=%s，OLED=%dms"
                % (
                    result.frame_ratio,
                    result.ratio,
                    result.confidence,
                    result.analysis_ms,
                    str(result.rect),
                    oled_ms,
                )
            )
        last_publish = now

    # OLED receives the clean frame before IDE annotations are drawn.
    if display is not None:
        try:
            display.update_if_due(frame, now_ms=now)
        except Exception as error:
            display.error_count += 1
            display.last_update = now
            if display.error_count == 1 or (display.error_count % 10) == 0:
                print(
                    "【OLED错误】刷新失败%d次：%s"
                    % (display.error_count, error)
                )

    if IDE_STREAM_ENABLED:
        annotate(frame, result, clock.fps(), oled_ms)
